    KEY `idx_wiki_pages_kb_id` (`knowledge_base_id`),
    `live_35` TINYINT GENERATED ALWAYS AS (CASE WHEN deleted_at IS NULL THEN 1 ELSE NULL END) STORED,
    UNIQUE KEY `idx_wiki_pages_kb_slug` (`knowledge_base_id`, `slug`, `live_35`)
) DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

